#pragma once
#include "wav.hpp"
#include <cstdio>
constexpr size_t MAX_STATE=190000;
struct NativeState{std::string format,identity;std::vector<unsigned char>component,controller;};
inline NativeState readState(const std::string&path,const std::string&format,const std::string&identity){NativeState s{format,identity,{},{}};if(path.empty())return s;std::ifstream f(path,std::ios::binary);require(bool(f),"Cannot open plug-in state");std::vector<unsigned char>b((std::istreambuf_iterator<char>(f)),{});require(b.size()>=24&&b.size()<=MAX_STATE&&!memcmp(b.data(),"AURST04",8),"Invalid state envelope");size_t at=8;auto block=[&](){require(at+4<=b.size(),"Truncated state");uint32_t n=u32(b.data()+at);at+=4;require(n<=MAX_STATE&&at+n<=b.size(),"Invalid state size");std::vector<unsigned char>v(b.begin()+at,b.begin()+at+n);at+=n;return v;};auto kind=block(),id=block();require(std::string(kind.begin(),kind.end())==format&&std::string(id.begin(),id.end())==identity,"State belongs to a different plug-in");s.component=block();s.controller=block();require(at==b.size(),"Trailing state bytes");return s;}
inline void writeState(const std::string&path,const NativeState&s){require(!path.empty(),"State output path required");std::vector<unsigned char>b={'A','U','R','S','T','0','4',0};auto append=[&](const auto&v){require(b.size()+v.size()+4<=MAX_STATE,"Plug-in state exceeds 190 KB");uint32_t n=v.size();for(int i=0;i<4;i++)b.push_back((n>>(i*8))&255);b.insert(b.end(),v.begin(),v.end());};append(s.format);append(s.identity);append(s.component);append(s.controller);std::string temp=path+".tmp";std::ofstream f(temp,std::ios::binary);f.write((char*)b.data(),b.size());f.close();require(bool(f)&&std::rename(temp.c_str(),path.c_str())==0,"Cannot save state atomically");}
struct HostOptions{bool edit=false;std::string input,output,stateIn,stateOut,pluginId;std::vector<std::string>parameters;HostOptions(int argc,char**argv){require(argc>=3,"Usage: host plugin (--edit | input.wav output.wav) [--state-in path] [--state-out path] [--plugin-id ID] [parameter=value]");int at=2;if(std::string(argv[at])=="--edit"){edit=true;at++;}else{require(argc>=4,"Input and output WAV required");input=argv[at++];output=argv[at++];}for(;at<argc;at++){std::string a=argv[at];if(a=="--state-in"||a=="--state-out"||a=="--plugin-id"){require(at+1<argc,"Option value missing");auto v=std::string(argv[++at]);if(a=="--state-in")stateIn=v;else if(a=="--state-out")stateOut=v;else pluginId=v;}else parameters.push_back(a);}}};
